/**
 * Bikram Sambat (B.S.) Nepali DatePicker v4.0.7
 * Enterprise Standalone Offline Engine for Smart Mobile & Optics ERP
 */
(function () {
    if (typeof HTMLElement.prototype.nepaliDatePicker !== 'undefined') return;

    const MONTH_NAMES = [
        "Baishakh", "Jestha", "Ashadh", "Shrawan", "Bhadra", "Ashwin",
        "Kartik", "Mangsir", "Poush", "Magh", "Falgun", "Chaitra"
    ];
    const DAY_NAMES = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];

    const BS_DAYS = {
        2075: [31, 31, 32, 31, 31, 30, 30, 30, 29, 30, 29, 31],
        2076: [31, 32, 31, 32, 31, 30, 30, 30, 29, 30, 29, 31],
        2077: [31, 32, 31, 32, 31, 30, 30, 30, 29, 30, 29, 31],
        2078: [31, 31, 31, 32, 31, 31, 30, 29, 30, 29, 30, 30],
        2079: [31, 31, 32, 31, 31, 31, 30, 29, 30, 29, 30, 30],
        2080: [31, 31, 31, 32, 31, 31, 30, 29, 30, 29, 30, 30],
        2081: [31, 31, 32, 31, 31, 31, 30, 29, 30, 29, 30, 30],
        2082: [31, 32, 31, 32, 31, 30, 30, 30, 29, 30, 29, 31],
        2083: [31, 31, 31, 32, 31, 31, 30, 29, 30, 29, 30, 30],
        2084: [31, 31, 32, 31, 31, 30, 30, 30, 29, 30, 30, 30],
        2085: [31, 32, 31, 32, 30, 31, 30, 30, 29, 30, 30, 30],
        2086: [31, 32, 31, 32, 31, 30, 30, 30, 29, 30, 30, 30],
        2087: [31, 32, 31, 32, 31, 30, 30, 30, 29, 30, 30, 31],
        2088: [31, 31, 32, 31, 31, 30, 30, 30, 29, 30, 30, 30],
        2089: [31, 32, 31, 32, 31, 30, 30, 30, 29, 30, 30, 30],
        2090: [31, 32, 31, 32, 31, 30, 30, 30, 29, 30, 30, 30]
    };

    function getMonthDays(year, month) {
        if (BS_DAYS[year]) return BS_DAYS[year][month - 1] || 30;
        return 30;
    }

    let activeInput = null;
    let box = null;

    function getBox() {
        let el = document.getElementById('ndp-nepali-box');
        if (!el) {
            el = document.createElement('div');
            el.id = 'ndp-nepali-box';
            el.className = 'ndp-nepali-box';
            document.body.appendChild(el);
        }
        return el;
    }

    function render(year, month, selectedDay) {
        box = getBox();
        const totalDays = getMonthDays(year, month);

        let yearOpts = '';
        for (let y = 2070; y <= 2090; y++) {
            yearOpts += `<option value="${y}" ${y === year ? 'selected' : ''}>${y}</option>`;
        }

        let monthOpts = '';
        MONTH_NAMES.forEach((m, idx) => {
            monthOpts += `<option value="${idx + 1}" ${idx + 1 === month ? 'selected' : ''}>${m}</option>`;
        });

        let daysHtml = '<tr>';
        let col = 0;
        for (let d = 1; d <= totalDays; d++) {
            const isSel = (d === selectedDay);
            const cls = isSel ? 'ndp-selected ndp-current-day' : '';
            daysHtml += `<td><a href="javascript:void(0)" class="${cls}" data-day="${d}">${d}</a></td>`;
            col++;
            if (col % 7 === 0 && d < totalDays) daysHtml += '</tr><tr>';
        }
        while (col % 7 !== 0) {
            daysHtml += '<td></td>';
            col++;
        }
        daysHtml += '</tr>';

        box.innerHTML = `
            <div class="ndp-header">
                <select id="ndp-year-select">${yearOpts}</select>
                <select id="ndp-month-select">${monthOpts}</select>
            </div>
            <table class="ndp-days">
                <thead><tr>${DAY_NAMES.map(d => `<th>${d}</th>`).join('')}</tr></thead>
                <tbody>${daysHtml}</tbody>
            </table>
        `;

        box.querySelector('#ndp-year-select').onchange = function () {
            render(parseInt(this.value, 10), month, selectedDay);
        };
        box.querySelector('#ndp-month-select').onchange = function () {
            render(year, parseInt(this.value, 10), selectedDay);
        };

        box.querySelectorAll('a[data-day]').forEach(a => {
            a.onclick = function (e) {
                e.preventDefault();
                const d = parseInt(this.dataset.day, 10);
                const val = `${year}-${String(month).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
                if (activeInput) {
                    activeInput.value = val;
                    activeInput.dispatchEvent(new Event('input', { bubbles: true }));
                    activeInput.dispatchEvent(new Event('change', { bubbles: true }));
                }
                close();
            };
        });
    }

    function open(input) {
        activeInput = input;
        box = getBox();

        let y = 2081, m = 1, d = 1;
        if (input.value && input.value.includes('-')) {
            const pts = input.value.split('-').map(Number);
            if (pts.length === 3 && pts[0] >= 2070) {
                y = pts[0]; m = pts[1]; d = pts[2];
            }
        }

        render(y, m, d);

        const r = input.getBoundingClientRect();
        box.style.top = (r.bottom + window.scrollY + 4) + 'px';
        box.style.left = (r.left + window.scrollX) + 'px';
        box.style.display = 'block';
    }

    function close() {
        if (box) box.style.display = 'none';
        activeInput = null;
    }

    document.addEventListener('click', function (e) {
        if (!box || box.style.display === 'none') return;
        if (activeInput && (e.target === activeInput || activeInput.contains(e.target))) return;
        if (box.contains(e.target)) return;
        close();
    });

    window.addEventListener('resize', close);

    HTMLElement.prototype.nepaliDatePicker = function () {
        this.addEventListener('focus', () => open(this));
        this.addEventListener('click', () => open(this));
        return this;
    };
})();
